<script setup lang="ts">
import {ElButton,ElDialog,ElInput,ElSelect,ElOption,ElTable,ElTableColumn} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {confirmAction} from '../../shared/confirm'
import {api,type Account} from '../../api'
import AdminListPager from '../../shared/list/AdminListPager.vue'
import AdminStatusBadge from '../../shared/list/AdminStatusBadge.vue'
import AdminSelectionBar from '../../shared/list/AdminSelectionBar.vue'
import AdminSelectedRowsDialog from '../../shared/list/AdminSelectedRowsDialog.vue'
import {base,reasonText,money,incomeLabel,withdrawalLabel,type Restaurant,type PageResult,type DiningAccount,type DiningWithdrawal,type DiningIncome} from './types'
import './dining.css'
const props=defineProps<{account:Account}>(),canManage=computed(()=>props.account.permissionCodes.includes('dining.finance.manage'))
const restaurants=ref<Restaurant[]>([]),restaurantId=ref(''),detail=ref<DiningAccount|null>(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const withdrawalSelectionVersion=ref(0),incomeSelectionVersion=ref(0)
const emptyQuery=()=>({page:1,pageSize:20,search:'',status:'',dateFrom:'',dateTo:''})
const incomeQuery=ref(emptyQuery()),withdrawalQuery=ref(emptyQuery())
const selectedWithdrawals=ref<DiningWithdrawal[]>([]),selectedIncomes=ref<DiningIncome[]>([]),comparison=ref(false),comparisonRows=ref<Record<string,unknown>[]>([])
const editing=ref<DiningWithdrawal|null>(null),decision=ref<'approve'|'reject'>('approve'),reason=ref(''),reviewError=ref('')
let generation=0,restaurantGeneration=0
function params(){const result=new URLSearchParams();for(const [prefix,values] of [['income',incomeQuery.value],['withdrawal',withdrawalQuery.value]] as const)for(const [key,value] of Object.entries(values))result.set(prefix+key[0]!.toUpperCase()+key.slice(1),String(value));return result}
async function loadRestaurants(){const current=++restaurantGeneration;restaurants.value=[];error.value='';try{const all:Restaurant[]=[];let page=1,total=0;do{const result=await api<PageResult<Restaurant>>(`${base}/restaurants?pageSize=100&page=${page++}`);if(current!==restaurantGeneration)return;all.push(...result.items);total=result.total;if(!result.items.length)break}while(all.length<total);restaurants.value=all;if(!restaurantId.value&&all.length)restaurantId.value=all[0]!.id}catch(e){if(current===restaurantGeneration)error.value=reasonText(e)}}
async function load(){const current=++generation;detail.value=null;selectedWithdrawals.value=[];selectedIncomes.value=[];comparison.value=false;if(!restaurantId.value)return;loading.value=true;error.value='';try{const result=await api<DiningAccount>(`${base}/restaurants/${restaurantId.value}/account?${params()}`);if(current===generation)detail.value=result}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
function query(kind:'income'|'withdrawal'){if(busy.value)return;(kind==='income'?incomeQuery:withdrawalQuery).value={...(kind==='income'?incomeQuery:withdrawalQuery).value,page:1};void load()}
function paginate(kind:'income'|'withdrawal',page:number,pageSize:number){if(busy.value)return;const target=kind==='income'?incomeQuery:withdrawalQuery;target.value={...target.value,page,pageSize};void load()}
function compare(kind:'income'|'withdrawal'){comparisonRows.value=kind==='income'?selectedIncomes.value.map(r=>({record:r.orderNo,amount:money(r.commissionFen),status:incomeLabel(r.status),reason:r.reason})):selectedWithdrawals.value.map(r=>({record:r.id,amount:money(r.amountFen),status:withdrawalLabel(r.status),reason:r.reason}));comparison.value=true}
function openReview(row:DiningWithdrawal){if(!canManage.value||busy.value||row.status!=='PENDING')return;editing.value={...row};decision.value='approve';reason.value='';reviewError.value=''}
async function closeReview(done?:()=>void){if(busy.value)return;if((reason.value.trim()||decision.value!=='approve')&&!await confirmAction('审核内容尚未提交，确定关闭吗？'))return;editing.value=null;done?.()}
async function review(){const row=editing.value;if(!row||busy.value||!canManage.value)return;if(decision.value==='reject'&&!reason.value.trim()){reviewError.value='驳回时请填写原因。';return}busy.value=true;reviewError.value='';const target=restaurantId.value,current=generation,actor=props.account.accountId;try{await api(`${base}/restaurants/${target}/withdrawals/${row.id}/${decision.value}`,{method:'POST',body:JSON.stringify({revision:row.revision,reason:reason.value.trim()})});if(current===generation&&actor===props.account.accountId){editing.value=null;await load();notice.value='提现审核结果已保存。'}}catch(e){if(current===generation)reviewError.value=`${reasonText(e)}；说明已保留，请刷新核对状态。`}finally{if(actor===props.account.accountId)busy.value=false}}
watch(restaurantId,()=>{incomeQuery.value=emptyQuery();withdrawalQuery.value=emptyQuery();editing.value=null;load()})
watch(()=>JSON.stringify([props.account.accountId,props.account.permissionCodes]),()=>{generation++;restaurantGeneration++;detail.value=null;editing.value=null;busy.value=false;restaurantId.value='';notice.value='';loadRestaurants()},{immediate:true})
</script>
<template>
<section class="page-content dining-page admin-list-page"><header class="page-heading"><div><h1>餐饮佣金与提现</h1><p>佣金由履约前置仓利润承担；审核通过只进入待打款。</p></div></header>
<section class="panel"><div class="toolbar"><label>餐饮店 <el-select v-model="restaurantId" aria-label="餐饮店" :disabled="busy" style="width:280px"><el-option v-for="r in restaurants" :key="r.id" :value="r.id" :label="r.name"/></el-select></label><el-button :loading="loading" :disabled="busy" @click="restaurantId?load():loadRestaurants()">刷新</el-button></div><p v-if="error" class="error" role="alert">{{error}} <el-button @click="restaurantId?load():loadRestaurants()">重试</el-button></p><p v-if="notice" role="status">{{notice}}</p><p v-if="loading" role="status">正在读取佣金账户…</p><p v-if="!loading&&!restaurants.length&&!error">暂无餐饮店。</p>
<template v-if="detail"><div class="balance"><div>可申请提现<strong>{{money(detail.availableFen)}}</strong></div><div>待满足条件<strong>{{money(detail.pendingFen)}}</strong></div><div>待核对<strong>{{money(detail.heldFen)}}</strong></div><div>提现占用<strong>{{money(detail.frozenFen)}}</strong></div></div>
<h2>提现申请</h2><form class="toolbar" @submit.prevent="query('withdrawal')"><label>申请编号 / 说明<el-input v-model="withdrawalQuery.search" aria-label="提现检索" maxlength="120"/></label><label>状态<el-select v-model="withdrawalQuery.status" aria-label="提现状态" clearable><el-option label="全部" value=""/><el-option v-for="s in ['PENDING','APPROVED','REJECTED']" :key="s" :value="s" :label="withdrawalLabel(s)"/></el-select></label><label>申请开始<input v-model="withdrawalQuery.dateFrom" type="date"/></label><label>申请结束<input v-model="withdrawalQuery.dateTo" type="date"/></label><el-button native-type="submit" type="primary" :disabled="busy">查询</el-button><el-button :disabled="busy" @click="withdrawalQuery=emptyQuery();load()">重置</el-button></form>
<AdminSelectionBar :count="selectedWithdrawals.length" unit="笔" :loading="loading||busy" @clear="selectedWithdrawals=[];withdrawalSelectionVersion++"><el-button :disabled="!selectedWithdrawals.length" @click="compare('withdrawal')">对比所选申请</el-button></AdminSelectionBar>
<el-table :key="withdrawalSelectionVersion" class="admin-list-table" :data="detail.withdrawals" empty-text="暂无提现申请" @selection-change="selectedWithdrawals=$event"><el-table-column type="selection" width="50"/><el-table-column label="申请编号" prop="id" min-width="180"/><el-table-column label="金额" width="120" align="right"><template #default="{row}">{{money(row.amountFen)}}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{row}"><AdminStatusBadge :status="row.status" :label="withdrawalLabel(row.status)" :tone="row.status==='APPROVED'?'pending':row.status==='REJECTED'?'danger':'pending'"/></template></el-table-column><el-table-column prop="createdAt" label="申请时间" min-width="190"/><el-table-column prop="reason" label="审核说明" min-width="180"/><el-table-column v-if="canManage" label="操作" fixed="right" width="110"><template #default="{row}"><el-button v-if="row.status==='PENDING'" link :disabled="busy" @click="openReview(row as DiningWithdrawal)">审核</el-button><span v-else>—</span></template></el-table-column></el-table>
<AdminListPager v-if="detail.withdrawalPagination" :page="withdrawalQuery.page" :page-size="withdrawalQuery.pageSize" :total="detail.withdrawalPagination.total" :loading="loading||busy" @change="(p,s)=>paginate('withdrawal',p,s)"/><p v-else class="muted">当前响应缺少历史分页信息，请更新服务端后重新读取。</p>
<h2>佣金明细</h2><form class="toolbar" @submit.prevent="query('income')"><label>订单号 / 桌号 / 说明<el-input v-model="incomeQuery.search" aria-label="佣金检索" maxlength="120"/></label><label>状态<el-select v-model="incomeQuery.status" aria-label="佣金状态" clearable><el-option label="全部" value=""/><el-option v-for="s in ['ESTIMATED','PENDING','HELD','AVAILABLE']" :key="s" :value="s" :label="incomeLabel(s)"/></el-select></label><label>订单开始<input v-model="incomeQuery.dateFrom" type="date"/></label><label>订单结束<input v-model="incomeQuery.dateTo" type="date"/></label><el-button native-type="submit" type="primary" :disabled="busy">查询</el-button><el-button :disabled="busy" @click="incomeQuery=emptyQuery();load()">重置</el-button></form>
<AdminSelectionBar :count="selectedIncomes.length" unit="笔" :loading="loading" @clear="selectedIncomes=[];incomeSelectionVersion++"><el-button :disabled="!selectedIncomes.length" @click="compare('income')">对比所选佣金</el-button></AdminSelectionBar>
<el-table :key="incomeSelectionVersion" class="admin-list-table" :data="detail.incomes" empty-text="暂无佣金记录" @selection-change="selectedIncomes=$event"><el-table-column type="selection" width="50"/><el-table-column prop="orderNo" label="订单" min-width="180"/><el-table-column prop="tableNumber" label="桌号" width="90"/><el-table-column label="佣金" width="120" align="right"><template #default="{row}">{{money(row.commissionFen)}}</template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{row}"><AdminStatusBadge :status="row.status" :label="incomeLabel(row.status)" :tone="row.status==='AVAILABLE'?'success':row.status==='HELD'?'danger':'pending'"/></template></el-table-column><el-table-column prop="reason" label="说明" min-width="220"/><el-table-column prop="availableAt" label="可提现时间" min-width="190"/></el-table>
<AdminListPager v-if="detail.incomePagination" :page="incomeQuery.page" :page-size="incomeQuery.pageSize" :total="detail.incomePagination.total" :loading="loading||busy" @change="(p,s)=>paginate('income',p,s)"/><p v-else class="muted">当前响应缺少历史分页信息，请更新服务端后重新读取。</p><p class="muted">筛选与分页只影响历史明细，余额始终由服务器完整计算。</p>
</template></section>
<el-dialog :model-value="!!editing" title="提现审核" width="min(560px,94vw)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy" :before-close="closeReview"><template v-if="editing"><p>申请 {{editing.id}} · {{money(editing.amountFen)}}</p><p>审核通过仅记录审核结果，款项仍待打款。</p><label>审核结果<el-select v-model="decision" aria-label="审核结果" :disabled="busy"><el-option value="approve" label="通过，待打款"/><el-option value="reject" label="驳回"/></el-select></label><label>审核说明<el-input v-model="reason" aria-label="审核说明" type="textarea" maxlength="500" :disabled="busy" placeholder="驳回须填写原因"/></label><p v-if="reviewError" class="error" role="alert">{{reviewError}}</p></template><template #footer><el-button :disabled="busy" @click="closeReview()">取消</el-button><el-button type="primary" :loading="busy" @click="review">确认审核</el-button></template></el-dialog>
<AdminSelectedRowsDialog v-model="comparison" title="所选财务记录对比" :columns="[{key:'record',label:'记录'},{key:'amount',label:'金额'},{key:'status',label:'状态'},{key:'reason',label:'说明'}]" :rows="comparisonRows"/>
</section></template>
